import os, requests

res = requests.post(
    '{{WA_API_BASE}}/api/v1/messages',
    headers={
        'Authorization': f"Bearer {os.environ['SM_API_KEY']}",
        'Idempotency-Key': 'ticket-2291-refund',
    },
    json={
      "to": "+919812345678",
      "type": "text",
      "text": {
        "body": "Hi Asha, your refund for order #1042 was processed today. It reaches your account in 3–5 working days."
      },
      "clientReference": "ticket-2291"
    },
)

data = res.json()['data']
print(data['id'], data['status'])
